<?php
/** Local open-weight models: why run locally, Ollama, GGUF and llama.cpp, hardware and quantisation, licences, using them from code. */

return [
    'id' => 'local-llm', 'family' => 'llm', 'after' => 'llm-api',
    'title' => L('Modelli locali open-weight', 'Local Open-weight Models'), 'short' => L('LLM locali', 'Local LLMs'), 'level' => L('Avanzato', 'Advanced'),
    'desc' => L('Far girare un LLM sul tuo computer: quando conviene, Ollama, formato GGUF e llama.cpp, memoria e quantizzazione, licenze, uso dal codice.', 'Running an LLM on your own computer: when it pays off, Ollama, the GGUF format and llama.cpp, memory and quantisation, licences, use from code.'),
    'lessons' => [
        lesson('why', L('Perché in locale', 'Why local'), [
            P('I modelli **open-weight** (Llama, Mistral, Qwen, Gemma, DeepSeek e altri) pubblicano i pesi: puoi scaricarli e farli girare sulle tue macchine. Vantaggi: i dati **non escono** dal computer, funzionano **offline**, nessun costo per token e pieno controllo della versione.', '**Open-weight** models (Llama, Mistral, Qwen, Gemma, DeepSeek and others) publish their weights: you can download them and run them on your own machines. Advantages: data **never leaves** the computer, they work **offline**, no per-token cost and full control of the version.'),
            P('Svantaggi: i modelli che girano su un portatile sono in genere meno capaci dei migliori modelli in cloud, servono hardware adeguato e manutenzione. Ottimi per dati riservati, prototipi, compiti ripetitivi e ambienti senza rete.', 'Drawbacks: models that run on a laptop are generally less capable than the best cloud models, and they need suitable hardware and upkeep. Great for confidential data, prototypes, repetitive tasks and offline environments.'),
            Tip('“Open-weight” non sempre vuol dire “open source”: i pesi sono scaricabili, ma dati e codice di addestramento spesso no, e la licenza può avere limiti.', '“Open-weight” does not always mean “open source”: weights are downloadable, but training data and code often are not, and the licence may have limits.'),
        ], [
            Q('w1', L('Qual è il vantaggio principale dei modelli locali per la privacy?', 'What is local models’ main privacy advantage?'), [L('I dati non escono dal computer', 'Data never leaves the computer'), L('Sono sempre più intelligenti', 'They are always smarter'), L('Non servono pesi', 'No weights are needed'), L('Hanno più token', 'They have more tokens')], 0, L('Niente invio a terzi.', 'Nothing sent to third parties.')),
            Q('w2', L('Che cosa significa open-weight?', 'What does open-weight mean?'), [L('I pesi del modello sono scaricabili', 'The model weights are downloadable'), L('Il modello pesa poco', 'The model is light'), L('Tutto è open source', 'Everything is open source'), L('È gratis in cloud', 'It is free in the cloud')], 0, L('Ma non sempre dati e codice.', 'But not always data and code.')),
            Q('w3', L('Un limite dei modelli su portatile è…', 'A limit of laptop models is…'), [L('Sono in genere meno capaci dei migliori in cloud', 'They are generally less capable than the best cloud ones'), L('Non funzionano offline', 'They do not work offline'), L('Mandano i dati in rete', 'They send data online'), L('Costano per token', 'They cost per token')], 0, L('Dipende dalla memoria disponibile.', 'It depends on available memory.')),
        ], task('text', L('Indica per ciascun caso `locale` o `cloud`, uno per riga come `caso: scelta`. Casi: `analizzare cartelle cliniche senza farle uscire dall’ospedale`, `ottenere la massima qualità su un problema di ricerca difficile`.', 'For each case write `local` or `cloud`, one per line as `case: choice`. Cases: `analyse medical records without them leaving the hospital`, `get top quality on a hard research problem`.'), '', [re('(cliniche|medical)[^:\n]*:\s*(locale|local)', L('I dati sanitari restano in locale', 'Health data stays local')), re('(qualità|quality)[^:\n]*:\s*cloud', L('La massima qualità è in cloud', 'Top quality is in the cloud'))], '', "analizzare cartelle cliniche senza farle uscire dall’ospedale: locale\nottenere la massima qualità su un problema di ricerca difficile: cloud"), [
            dMatch(pMatch(), [[L('Privacy', 'Privacy'), L('I dati restano qui', 'Data stays here')], ['Offline', L('Funziona senza rete', 'Works without network')], [L('Costo', 'Cost'), L('Niente prezzo per token', 'No per-token price')], [L('Limite', 'Limit'), L('Meno capacità su hardware piccolo', 'Less capability on small hardware')]], L('Pro e contro del locale.', 'Pros and cons of local.')),
            dFlash(pFlash(), [[L('Un modello locale funziona senza internet', 'A local model works without internet'), true], [L('Open-weight vuol dire sempre open source completo', 'Open-weight always means fully open source'), false], [L('Con un modello locale non si paga a token', 'With a local model you do not pay per token'), true], [L('I modelli locali sono sempre i più capaci', 'Local models are always the most capable'), false]], L('Scegliere in base al caso.', 'Choose case by case.')),
        ]),
        lesson('ollama', L('Ollama', 'Ollama'), [
            P('**Ollama** è il modo più semplice per iniziare: un programma per macOS, Linux e Windows che scarica e fa girare modelli con un comando. Avvia anche un **server locale** con un’API HTTP sulla porta 11434.', '**Ollama** is the easiest way to start: a program for macOS, Linux and Windows that downloads and runs models with one command. It also starts a **local server** with an HTTP API on port 11434.'),
            C('ollama pull llama3.2          # scarica il modello
ollama run llama3.2           # chat nel terminale
ollama list                   # modelli scaricati

curl http://localhost:11434/api/chat -d \'{
  "model": "llama3.2",
  "messages": [{"role": "user", "content": "Ciao!"}],
  "stream": false
}\'', 'bash'),
            P('Ollama espone anche un’API **compatibile con quella di OpenAI** su `/v1`: molti strumenti e librerie possono usare un modello locale cambiando solo l’indirizzo.', 'Ollama also exposes an **OpenAI-compatible** API at `/v1`: many tools and libraries can use a local model by changing only the address.'),
        ], [
            Q('o1', L('Quale comando scarica un modello?', 'Which command downloads a model?'), ['ollama pull', 'ollama get', 'ollama download', 'ollama fetch'], 0, L('`run` lo scarica anche se manca.', '`run` also downloads it if missing.')),
            Q('o2', L('Su quale porta risponde il server di Ollama?', 'Which port does the Ollama server answer on?'), ['11434', '80', '3306', '8080'], 0, L('localhost:11434.', 'localhost:11434.')),
            Q('o3', L('A che cosa serve l’API compatibile OpenAI?', 'What is the OpenAI-compatible API for?'), [L('Usare strumenti esistenti con un modello locale', 'Using existing tools with a local model'), L('Pagare meno OpenAI', 'Paying OpenAI less'), L('Scaricare i pesi di GPT', 'Downloading GPT weights'), L('Niente', 'Nothing')], 0, L('Cambi solo l’indirizzo.', 'You only change the address.')),
        ], task('bash', L('Scrivi i comandi per scaricare il modello `mistral` con Ollama e poi avviarlo in chat.', 'Write the commands to download the `mistral` model with Ollama and then start it in chat.'), '', [re('ollama\s+pull\s+mistral', L('Lo scarichi', 'You download it')), re('ollama\s+run\s+mistral', L('Lo avvii', 'You run it'))], '', "ollama pull mistral\nollama run mistral"), [
            dMatch(pMatch(), [['ollama pull', L('Scarica', 'Downloads')], ['ollama run', L('Avvia la chat', 'Starts the chat')], ['ollama list', L('Elenca i modelli', 'Lists models')], ['/api/chat', L('API di chat', 'Chat API')], ['/v1', L('API compatibile OpenAI', 'OpenAI-compatible API')]], L('I comandi di Ollama.', 'Ollama commands.')),
            dOrder(pSort(), ['ollama pull llama3.2', 'ollama list', 'ollama run llama3.2'], L('Scarica, controlla, usa.', 'Download, check, use.')),
        ]),
        lesson('gguf', L('GGUF e llama.cpp', 'GGUF and llama.cpp'), [
            P('**llama.cpp** è il motore in C/C++ che fa girare LLM su CPU, GPU e chip Apple; Ollama e molte altre app lo usano dietro le quinte. I modelli si distribuiscono in formato **GGUF**: un solo file che contiene pesi quantizzati e informazioni sul tokenizzatore.', '**llama.cpp** is the C/C++ engine that runs LLMs on CPUs, GPUs and Apple chips; Ollama and many other apps use it under the hood. Models are distributed in the **GGUF** format: a single file holding quantised weights and tokeniser information.'),
            C('# nome tipico di un file GGUF
Mistral-7B-Instruct-v0.3-Q4_K_M.gguf
#        7B = 7 miliardi di parametri   Instruct = addestrato a seguire istruzioni
#        Q4_K_M = quantizzato a circa 4 bit, variante bilanciata

llama-server -m Mistral-7B-Instruct-v0.3-Q4_K_M.gguf --port 8080', 'bash'),
            P('Il nome del file dice molto: dimensione (7B, 8B, 70B…), tipo (**Instruct** o “chat” per conversare, **base** per completare testo) e livello di quantizzazione (Q8 più fedele e pesante, Q4 più leggero).', 'The file name says a lot: size (7B, 8B, 70B…), type (**Instruct** or “chat” for conversation, **base** for completing text) and quantisation level (Q8 more faithful and heavier, Q4 lighter).'),
        ], [
            Q('g1', L('Che cosa contiene un file GGUF?', 'What does a GGUF file contain?'), [L('Pesi quantizzati e dati del tokenizzatore', 'Quantised weights and tokeniser data'), L('Solo il codice sorgente', 'Only source code'), L('Un video', 'A video'), L('Le chat degli utenti', 'Users’ chats')], 0, L('Tutto in un file.', 'All in one file.')),
            Q('g2', L('Che cosa indica “7B”?', 'What does “7B” mean?'), [L('7 miliardi di parametri', '7 billion parameters'), L('7 byte', '7 bytes'), L('Versione 7 beta', 'Version 7 beta'), L('7 lingue', '7 languages')], 0, L('B = billion.', 'B = billion.')),
            Q('g3', L('Per conversare, quale variante scegli?', 'To chat, which variant do you pick?'), [L('Instruct', 'Instruct'), L('Base', 'Base'), L('Q8', 'Q8'), L('Qualsiasi senza differenze', 'Any, no difference')], 0, L('Il base completa testo, non segue istruzioni.', 'Base completes text, it does not follow instructions.')),
        ], task('text', L('Spiega le tre parti del nome `Qwen2.5-14B-Instruct-Q5_K_M.gguf`, una per riga: dimensione, tipo, quantizzazione.', 'Explain the three parts of the name `Qwen2.5-14B-Instruct-Q5_K_M.gguf`, one per line: size, type, quantisation.'), '', [re('14\s*B[^\n]*(miliardi|billion)', L('La dimensione', 'The size')), re('Instruct[^\n]*(istruzion|instruction|chat|conversa)', L('Il tipo', 'The type')), re('Q5[^\n]*(5\s*bit|quantizz|quantis|quantiz)', L('La quantizzazione', 'The quantisation'))], '', "14B: 14 miliardi di parametri\nInstruct: addestrato a seguire istruzioni, adatto alla chat\nQ5_K_M: quantizzato a circa 5 bit"), [
            dMatch(pMatch(), [['llama.cpp', L('Motore di inferenza', 'Inference engine')], ['GGUF', L('Formato del file', 'File format')], ['Instruct', L('Segue istruzioni', 'Follows instructions')], ['Q4_K_M', L('Circa 4 bit', 'About 4 bits')], ['70B', L('70 miliardi di parametri', '70 billion parameters')]], L('Leggere il nome di un modello.', 'Reading a model name.')),
            dFlash(pFlash(), [[L('Ollama usa llama.cpp dietro le quinte', 'Ollama uses llama.cpp under the hood'), true], [L('Q8 è più leggero di Q4', 'Q8 is lighter than Q4'), false], [L('Un modello base è ideale per la chat', 'A base model is ideal for chat'), false], [L('llama.cpp gira anche sui chip Apple', 'llama.cpp also runs on Apple chips'), true]], L('Formati e varianti.', 'Formats and variants.')),
        ]),
        lesson('hardware', L('Memoria e hardware', 'Memory and hardware'), [
            P('La regola veloce: la memoria necessaria è circa **parametri × byte per parametro**, più un margine per il contesto. A 16 bit ogni parametro occupa 2 byte; a 8 bit 1 byte; a 4 bit mezzo byte.', 'The quick rule: memory needed is about **parameters × bytes per parameter**, plus a margin for the context. At 16 bits each parameter takes 2 bytes; at 8 bits 1 byte; at 4 bits half a byte.'),
            C('def memoria_gb(miliardi_parametri, bit):
    return miliardi_parametri * bit / 8          # GB, senza il margine per il contesto

print(memoria_gb(8, 16))    # 16.0 GB
print(memoria_gb(8, 4))     # 4.0 GB  → sta su un portatile con 16 GB
print(memoria_gb(70, 4))    # 35.0 GB → serve una macchina grossa', 'python'),
            P('Conta la memoria della **GPU** (VRAM) o, sui Mac con chip Apple, la memoria unificata. Se il modello non entra, gira lentissimo o non parte. Più contesto usi, più memoria serve in aggiunta.', 'What counts is **GPU** memory (VRAM) or, on Macs with Apple chips, unified memory. If the model does not fit, it runs very slowly or not at all. The more context you use, the more extra memory you need.'),
        ], [
            Q('h1', L('Quanta memoria serve per un modello da 8B a 4 bit, circa?', 'About how much memory does an 8B model at 4 bits need?'), ['4 GB', '32 GB', '0,5 GB', '64 GB'], 0, L('8 × 4 / 8 = 4.', '8 × 4 / 8 = 4.')),
            Q('h2', L('Quale memoria conta di più?', 'Which memory matters most?'), [L('Quella della GPU o la memoria unificata', 'GPU memory or unified memory'), L('Lo spazio su disco', 'Disk space'), L('La cache del browser', 'Browser cache'), L('La RAM della stampante', 'The printer’s RAM')], 0, L('Il modello deve starci dentro.', 'The model must fit in it.')),
            Q('h3', L('Un contesto più lungo…', 'A longer context…'), [L('Richiede più memoria', 'Needs more memory'), L('Libera memoria', 'Frees memory'), L('Non cambia niente', 'Changes nothing'), L('Rende il modello più piccolo', 'Makes the model smaller')], 0, L('Va messo in conto un margine.', 'Plan for a margin.')),
        ], task('python', L('Completa `memoria_gb` in modo che restituisca `miliardi_parametri * bit / 8`, poi stampa il risultato per 14 miliardi a 8 bit.', 'Complete `memoria_gb` so it returns `miliardi_parametri * bit / 8`, then print the result for 14 billion at 8 bits.'), "def memoria_gb(miliardi_parametri, bit):\n    ", [re('return\s+miliardi_parametri\s*\*\s*bit\s*/\s*8', L('La formula', 'The formula')), re('print\s*\(\s*memoria_gb\s*\(\s*14\s*,\s*8\s*\)\s*\)', L('Il caso 14B a 8 bit', 'The 14B at 8-bit case'))], '', "def memoria_gb(miliardi_parametri, bit):\n    return miliardi_parametri * bit / 8\n\nprint(memoria_gb(14, 8))"), [
            dMatch(pMatch(), [[L('8B a 16 bit', '8B at 16 bit'), '16 GB'], [L('8B a 8 bit', '8B at 8 bit'), '8 GB'], [L('8B a 4 bit', '8B at 4 bit'), '4 GB'], [L('70B a 4 bit', '70B at 4 bit'), '35 GB']], L('Parametri × bit / 8.', 'Parameters × bits / 8.')),
            dFlash(pFlash(), [[L('Un modello da 70B a 4 bit sta in 8 GB', 'A 70B model at 4 bits fits in 8 GB'), false], [L('Quantizzare riduce la memoria necessaria', 'Quantising reduces the memory needed'), true], [L('Sui Mac con chip Apple conta la memoria unificata', 'On Apple-chip Macs unified memory counts'), true], [L('Lo spazio su disco decide la velocità', 'Disk space decides speed'), false]], L('Fare i conti prima di scaricare.', 'Do the maths before downloading.')),
        ]),
        lesson('code', L('Licenze e uso dal codice', 'Licences and use from code'), [
            P('Ogni modello aperto ha la sua **licenza**: alcune sono permissive (come Apache 2.0 o MIT), altre sono licenze proprie con condizioni (limiti sull’uso commerciale oltre una certa scala, usi vietati, obbligo di citare). Leggila prima di usare un modello in un prodotto.', 'Every open model has its own **licence**: some are permissive (like Apache 2.0 or MIT), others are custom licences with conditions (limits on commercial use above a certain scale, forbidden uses, attribution duties). Read it before using a model in a product.'),
            C('import requests

r = requests.post("http://localhost:11434/api/chat", json={
    "model": "llama3.2",
    "messages": [{"role": "user", "content": "Riassumi in una frase: …"}],
    "stream": False,
})
print(r.json()["message"]["content"])', 'python'),
            P('Dal codice un modello locale si usa come un’API qualsiasi, solo all’indirizzo `localhost`. Attenzione a non esporre la porta su internet senza protezione: chiunque potrebbe usare il tuo modello e il tuo hardware.', 'From code a local model is used like any API, just at a `localhost` address. Take care not to expose the port to the internet without protection: anyone could use your model and your hardware.'),
        ], [
            Q('c1', L('Perché leggere la licenza di un modello aperto?', 'Why read an open model’s licence?'), [L('Può avere condizioni sull’uso commerciale', 'It may have conditions on commercial use'), L('Per sapere il colore', 'To know the colour'), L('Non serve', 'It is not needed'), L('Per installarlo', 'To install it')], 0, L('Non tutte sono uguali.', 'They are not all alike.')),
            Q('c2', L('Dove risponde il modello locale nell’esempio?', 'Where does the local model answer in the example?'), [L('localhost:11434', 'localhost:11434'), L('api.openai.com', 'api.openai.com'), L('Nel browser', 'In the browser'), L('Su un server remoto', 'On a remote server')], 0, L('Sul tuo computer.', 'On your computer.')),
            Q('c3', L('Che rischio c’è a esporre la porta su internet?', 'What is the risk of exposing the port to the internet?'), [L('Chiunque può usare il tuo modello e hardware', 'Anyone can use your model and hardware'), L('Nessuno', 'None'), L('Il modello diventa più veloce', 'The model gets faster'), L('Si cancellano i pesi', 'The weights get deleted')], 0, L('Proteggi o lascia locale.', 'Protect it or keep it local.')),
        ], task('python', L('Con `requests.post` chiama `http://localhost:11434/api/chat` con il modello `mistral`, un messaggio `user` e `"stream": False`, poi stampa `r.json()["message"]["content"]`.', 'With `requests.post` call `http://localhost:11434/api/chat` with model `mistral`, a `user` message and `"stream": False`, then print `r.json()["message"]["content"]`.'), "import requests\n", [re('requests\.post\s*\(\s*["\']http://localhost:11434/api/chat["\']', L('L’indirizzo locale', 'The local address')), re('["\']model["\']\s*:\s*["\']mistral["\']', L('Il modello', 'The model')), re('["\']stream["\']\s*:\s*False', L('Senza streaming', 'Without streaming')), re('print\s*\(\s*r\.json\s*\(\s*\)\s*\[\s*["\']message["\']\s*\]\s*\[\s*["\']content["\']\s*\]\s*\)', L('Stampi la risposta', 'You print the answer'))], '', "r = requests.post(\"http://localhost:11434/api/chat\", json={\n    \"model\": \"mistral\",\n    \"messages\": [{\"role\": \"user\", \"content\": \"Ciao\"}],\n    \"stream\": False,\n})\nprint(r.json()[\"message\"][\"content\"])"), [
            dMatch(pMatch(), [['Apache 2.0', L('Licenza permissiva', 'Permissive licence')], [L('Licenza propria', 'Custom licence'), L('Condizioni specifiche', 'Specific conditions')], ['localhost', L('Il tuo computer', 'Your computer')], ['"stream": False', L('Risposta tutta insieme', 'Answer all at once')]], L('Usare con criterio.', 'Use with care.')),
            dBug(pBug(), ['import requests', 'r = requests.post("http://localhost:11434/api/chat", json={', '    "model": "llama3.2", "messages": [{"role": "user", "content": "Ciao"}], "stream": False})', 'print(r.json()["choices"][0]["text"])'], 3, 'print(r.json()["message"]["content"])', L('L’API di Ollama mette la risposta in `message.content`.', 'Ollama’s API puts the answer in `message.content`.')),
        ]),
    ],
];
